export type SpecializationNode = {
  name: string;
  overview: string;
  professions: [string, string];
  skills: string[];
  regulated?: boolean;
};

export type CareerFieldNode = {
  name: string;
  specializations: SpecializationNode[];
};

export type IndustryNode = {
  slug: string;
  name: string;
  icon: string;
  color: string;
  description: string;
  fields: CareerFieldNode[];
};

const specialization = (
  name: string,
  overview: string,
  professions: [string, string],
  skills: string[],
  regulated = false,
): SpecializationNode => ({ name, overview, professions, skills, regulated });

const field = (name: string, ...specializations: SpecializationNode[]): CareerFieldNode => ({ name, specializations });

